const t = FILE_CONTENT;
// split by issue
const parts = t.split(/===== #(\d+) =====/);
// parts[0] empty, then alternating num, body
for (let i=1;i<parts.length;i+=2){
  const num=parts[i]; const body=parts[i+1]||'';
  const titleMatch = body.match(/^\s*([^\n]+)/);
  // count findings
  const findings = [...body.matchAll(/### \[(major|minor)(?:[^\]]*)\] ([^\n]+)/g)];
  console.log(`\n#${num}: ${titleMatch[1].trim()}`);
  console.log(`  findings: ${findings.length}`);
  findings.forEach(f=>console.log(`   [${f[1]}] ${f[2].trim()}`));
}

const t=FILE_CONTENT;
const seg=t.split(/===== #172 =====/)[1].split(/===== #173/)[0];
const blocks=seg.split(/### \[/).slice(1);
blocks.forEach((b,i)=>{
  const sev=b.match(/^(major|minor|[^\]]+)\]/)[1];
  const title=b.split('\n')[0].replace(/^[^\]]+\]\s*/,'');
  const loc=(b.match(/\*\*Location:\*\*\s*([^\n]+)/)||[])[1]||'?';
  console.log(`${i+1}. [${sev}] ${title}\n    LOC: ${loc}`);
});

